    std::uint8_t *aAbjurationLaneD = pWorkSpace->mAbjurationLaneD;
    std::uint8_t *aDivinationLaneA = pWorkSpace->mDivinationLaneA;
    std::uint8_t *aDivinationLaneB = pWorkSpace->mDivinationLaneB;
    std::uint8_t *aDivinationLaneC = pWorkSpace->mDivinationLaneC;
    std::uint8_t *aDivinationLaneD = pWorkSpace->mDivinationLaneD;
    std::uint8_t *aEvocationLaneA = pWorkSpace->mEvocationLaneA;
    std::uint8_t *aEvocationLaneB = pWorkSpace->mEvocationLaneB;
    std::uint8_t *aEvocationLaneC = pWorkSpace->mEvocationLaneC;
    std::uint8_t *aEvocationLaneD = pWorkSpace->mEvocationLaneD;
    std::uint8_t *aStasisLaneA = pWorkSpace->mStasisLaneA;
    std::uint8_t *aStasisLaneB = pWorkSpace->mStasisLaneB;
    std::uint8_t *aStasisLaneC = pWorkSpace->mStasisLaneC;
    std::uint8_t *aAlchemyLaneA = pWorkSpace->mAlchemyLaneA;
    std::uint8_t *aAlchemyLaneB = pWorkSpace->mAlchemyLaneB;
    std::uint8_t *aAlchemyLaneC = pWorkSpace->mAlchemyLaneC;
    std::uint8_t *aAlchemyLaneD = pWorkSpace->mAlchemyLaneD;
    std::uint8_t *aAuguryLaneA = pWorkSpace->mAuguryLaneA;
    std::uint8_t *aAuguryLaneB = pWorkSpace->mAuguryLaneB;
    std::uint8_t *aAuguryLaneC = pWorkSpace->mAuguryLaneC;
    std::uint8_t *aAuguryLaneD = pWorkSpace->mAuguryLaneD;
    std::uint8_t *aPsychicLaneA = pWorkSpace->mPsychicLaneA;
    std::uint8_t *aPsychicLaneB = pWorkSpace->mPsychicLaneB;
    std::uint8_t *aPsychicLaneC = pWorkSpace->mPsychicLaneC;
    std::uint8_t *aPsychicLaneD = pWorkSpace->mPsychicLaneD;
    std::uint8_t *aVoodooLaneA = pWorkSpace->mVoodooLaneA;
    std::uint8_t *aVoodooLaneB = pWorkSpace->mVoodooLaneB;
    std::uint8_t *aVoodooLaneC = pWorkSpace->mVoodooLaneC;
    std::uint8_t *aVoodooLaneD = pWorkSpace->mVoodooLaneD;
    std::uint8_t *aIceLaneA = pWorkSpace->mIceLaneA;
    std::uint8_t *aIceLaneB = pWorkSpace->mIceLaneB;
    std::uint8_t *aIceLaneC = pWorkSpace->mIceLaneC;
    std::uint8_t *aIceLaneD = pWorkSpace->mIceLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aIngress = *pIngress + 0x1D6B373D934C4588ULL;
    std::uint64_t aCarry = *pCarry + 0xD5BD5C8B10CF71C7ULL;
    std::uint64_t aWandererA = *pWandererA + 0xED58D9AC06D47B93ULL;
    std::uint64_t aWandererB = *pWandererB + 0xBE0617EBE26BF0F2ULL;
    std::uint64_t aWandererC = *pWandererC + 0xA0B5CB3E2CA895A9ULL;
    std::uint64_t aWandererD = *pWandererD + 0x7783C60978AE7AFULL;
    std::uint64_t aWandererE = *pWandererE + 0x27C86BD620F3221BULL;
    std::uint64_t aWandererF = *pWandererF + 0x3BA6F64EEC854052ULL;
    std::uint64_t aWandererG = *pWandererG + 0xDA2F5412DA845227ULL;
    std::uint64_t aWandererH = *pWandererH + 0xCD8660AF648BA263ULL;
    std::uint64_t aWandererI = *pWandererI + 0x3381F3F65D01FC45ULL;
    std::uint64_t aWandererJ = *pWandererJ + 0x63A7C4412469DE59ULL;
    std::uint64_t aWandererK = *pWandererK + 0xB431FD99DCFCE793ULL;

    ////////////////////////////////////////////////////////
    //
    // Secret material derivation, across 6 domains.
    //
    // Domain 1 of 6, key a rotate:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_A(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeyRotateAConstants), &(mDomainBundleInbuilt.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeyRotateASalts,
                    &(mDomainBundleEphemeralA.mKeyRotateAConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_A(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeyRotateAConstants), &(mDomainBundleEphemeralA.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeyRotateASalts,
                    &(mDomainBundleEphemeralB.mKeyRotateAConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_A(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeyRotateAConstants), &(mDomainBundleEphemeralB.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeyRotateASalts,
                    &(pWorkSpace->mDomainBundle.mKeyRotateAConstants));
    //
    // Domain 2 of 6, key b rotate:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_B(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeyRotateBConstants), &(mDomainBundleInbuilt.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeyRotateBSalts,
                    &(mDomainBundleEphemeralA.mKeyRotateBConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_B(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeyRotateBConstants), &(mDomainBundleEphemeralA.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeyRotateBSalts,
                    &(mDomainBundleEphemeralB.mKeyRotateBConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_B(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeyRotateBConstants), &(mDomainBundleEphemeralB.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeyRotateBSalts,
                    &(pWorkSpace->mDomainBundle.mKeyRotateBConstants));
    //
    // Domain 3 of 6, key a spawn:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_C(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnAConstants), &(mDomainBundleInbuilt.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeySpawnASalts,
                    &(mDomainBundleEphemeralA.mKeySpawnAConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnAConstants), &(mDomainBundleEphemeralA.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnASalts,
                    &(mDomainBundleEphemeralB.mKeySpawnAConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnAConstants), &(mDomainBundleEphemeralB.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnASalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnAConstants));
    //
    // Domain 4 of 6, key b spawn:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_D(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnBConstants), &(mDomainBundleInbuilt.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralA.mKeySpawnBConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnBConstants), &(mDomainBundleEphemeralA.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralB.mKeySpawnBConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnBConstants), &(mDomainBundleEphemeralB.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnBSalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnBConstants));
    //
    // Domain 5 of 6, twist:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_E(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mTwistConstants), &(mDomainBundleInbuilt.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mTwistSalts,
                    &(mDomainBundleEphemeralA.mTwistConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mTwistConstants), &(mDomainBundleEphemeralA.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mTwistSalts,
                    &(mDomainBundleEphemeralB.mTwistConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mTwistConstants), &(mDomainBundleEphemeralB.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mTwistSalts,
                    &(pWorkSpace->mDomainBundle.mTwistConstants));
    //
    // Domain 6 of 6, seed:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_F(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mSeedConstants), &(mDomainBundleInbuilt.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mSeedSalts,
                    &(mDomainBundleEphemeralA.mSeedConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mSeedConstants), &(mDomainBundleEphemeralA.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mSeedSalts,
                    &(mDomainBundleEphemeralB.mSeedConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mSeedConstants), &(mDomainBundleEphemeralB.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mSeedSalts,
                    &(pWorkSpace->mDomainBundle.mSeedConstants));
    //
    ////////////////////////////////////////////////////////

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgD;

    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    // src: [source, nonce]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::SEED_A(PARAMS_SEED);

    //
    // src: [$ice]
    // dst: [$rainbow]
    //
    TwistExpander_Betelgeuse_Arx::SEED_B(PARAMS_SEED);

    //
    // ent: [$ice]
    // src: [$rainbow]
    // dst: [$alchemy]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aIceLaneA, aIceLaneB, aIceLaneC, aIceLaneD, // entropy lanes
        aRainbowLaneA, aRainbowLaneB, aRainbowLaneC, aRainbowLaneD,  // input lanes
        aAlchemyLaneA, aAlchemyLaneB, aAlchemyLaneC, aAlchemyLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$alchemy]
    // dst: [$augury]
    //
    TwistExpander_Betelgeuse_Arx::SEED_C(PARAMS_SEED);

    //
    // src: [$augury]
    // dst: [$spirit]
    //
    TwistExpander_Betelgeuse_Arx::SEED_D(PARAMS_SEED);

    //
    // ent: [$augury]
    // src: [$spirit]
    // dst: [$divination]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aAuguryLaneA, aAuguryLaneB, aAuguryLaneC, aAuguryLaneD, // entropy lanes
        aSpiritLaneA, aSpiritLaneB, aSpiritLaneC, aSpiritLaneD,  // input lanes
        aDivinationLaneA, aDivinationLaneB, aDivinationLaneC, aDivinationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$divination]
    // dst: [$psychic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_E(PARAMS_SEED);

    //
    // src: [$psychic]
    // dst: [$voodoo]
    //
    TwistExpander_Betelgeuse_Arx::SEED_F(PARAMS_SEED);

    //
    // ent: [$psychic]
    // src: [$voodoo]
    // dst: [$vapor]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aPsychicLaneA, aPsychicLaneB, aPsychicLaneC, aPsychicLaneD, // entropy lanes
        aVoodooLaneA, aVoodooLaneB, aVoodooLaneC, aVoodooLaneD,  // input lanes
        aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$vapor]
    // dst: [$sonic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_G(PARAMS_SEED);

    //
    // src: [$sonic]
    // dst: [$planar]
    //
    TwistExpander_Betelgeuse_Arx::SEED_H(PARAMS_SEED);

    //
    // ent: [$sonic]
    // src: [$planar]
    // dst: [$frost]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aSonicLaneA, aSonicLaneB, aSonicLaneC, aSonicLaneD, // entropy lanes
        aPlanarLaneA, aPlanarLaneB, aPlanarLaneC, aPlanarLaneD,  // input lanes
        aFrostLaneA, aFrostLaneB, aFrostLaneC, aFrostLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$frost]
    // dst: [$gloom]
    //
    TwistExpander_Betelgeuse_Arx::SEED_I(PARAMS_SEED);

    //
    // src: [$gloom]
    // dst: [$lightning]
    //
    TwistExpander_Betelgeuse_Arx::SEED_J(PARAMS_SEED);

    //
    // ent: [$gloom]
    // src: [$lightning]
    // dst: [$wind]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aGloomLaneA, aGloomLaneB, aGloomLaneC, aGloomLaneD, // entropy lanes
        aLightningLaneA, aLightningLaneB, aLightningLaneC, aLightningLaneD,  // input lanes
        aWindLaneA, aWindLaneB, aWindLaneC, aWindLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$wind]
    // dst: [$shadow]
    //
    TwistExpander_Betelgeuse_Arx::SEED_K(PARAMS_SEED);

    //
    // src: [$shadow]
    // dst: [$fire]
    //
    TwistExpander_Betelgeuse_Arx::SEED_L(PARAMS_SEED);

    //
    // ent: [$shadow]
    // src: [$fire]
    // dst: [$kinetic]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aShadowLaneA, aShadowLaneB, aShadowLaneC, aShadowLaneD, // entropy lanes
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD,  // input lanes
        aKineticLaneA, aKineticLaneB, aKineticLaneC, aKineticLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    TwistExpander_Betelgeuse_Arx::SEED_M(PARAMS_SEED);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_N(PARAMS_SEED);

    //
    // ent: [$evocation]
    // src: [$runic]
    // dst: [$abjuration]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aEvocationLaneA, aEvocationLaneB, aEvocationLaneC, aEvocationLaneD, // entropy lanes
        aRunicLaneA, aRunicLaneB, aRunicLaneC, aRunicLaneD,  // input lanes
        aAbjurationLaneA, aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Betelgeuse_Arx::SEED_O(PARAMS_SEED);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Betelgeuse_Arx::SEED_P(PARAMS_SEED);

    //
    // ent: [$aether]
    // src: [$lunar]
    // dst: [$earth]
    //

    TwistDiffuse::DiffuseWithDomainWords(
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD, // entropy lanes
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD,  // input lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$earth]
    // dst: [$crystal]
    //
    TwistExpander_Betelgeuse_Arx::SEED_Q(PARAMS_SEED);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main seed loops into destination
    //
    TwistSquash::SquashC(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    *pIngress = aIngress;
    *pCarry = aCarry;
    *pWandererA = aWandererA;
    *pWandererB = aWandererB;
    *pWandererC = aWandererC;
    *pWandererD = aWandererD;
    *pWandererE = aWandererE;
    *pWandererF = aWandererF;
    *pWandererG = aWandererG;
    *pWandererH = aWandererH;
    *pWandererI = aWandererI;
    *pWandererJ = aWandererJ;
    *pWandererK = aWandererK;

    ////////////////////////////////////////////////////////
    //
    // Independent key-row flows
    //
    // Key flow — A / A

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_A_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_A_B(PARAMS_SEED);

    KeyDiffuse_A_A_A(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_A_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_A_D(PARAMS_SEED);

    KeyDiffuse_B_A_A(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BETELGEUSE_KEY_A_A_IceLaneA, BETELGEUSE_KEY_A_A_IceLaneB, BETELGEUSE_KEY_A_A_IceLaneC, BETELGEUSE_KEY_A_A_IceLaneD, &(pWorkSpace->mKeyBoxA[0U][0]));

    // Key flow — A / B

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_B(PARAMS_SEED);

    KeyDiffuse_A_A_B(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BETELGEUSE_KEY_A_B_IceLaneA, BETELGEUSE_KEY_A_B_IceLaneB, BETELGEUSE_KEY_A_B_IceLaneC, BETELGEUSE_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
